const phonemeMap={p:'PP',b:'PP',m:'PP',f:'FF',v:'FF','θ':'TH','ð':'TH',t:'DD',d:'DD','ɾ':'DD',k:'kk',g:'kk','ɡ':'kk','ŋ':'kk',n:'nn',l:'nn',r:'RR','ɹ':'RR',s:'SS',z:'SS','ʃ':'CH','ʒ':'CH','tʃ':'CH','dʒ':'CH',i:'I','ɪ':'I',j:'I',e:'E','ɛ':'E','æ':'aa',a:'aa','ɑ':'aa','ʌ':'aa','ə':'aa','ɜ':'E',o:'O','ɔ':'O',u:'U','ʊ':'U',w:'U'};
