let sequence=[];function makeSequence(){let t=0;sequence=[{at:0,type:'enter'}];for(const [id,pause] of [['intro',1.2],['thought',1],['doubt',1.2],['gift',0]]){sequence.push({at:t,type:'voice',id});t+=clips.find(c=>c.id===id).duration;if(id==='intro')sequence.push({at:t,type:'listen'});if(id==='thought')sequence.push({at:t,type:'doubt'});if(id==='doubt')sequence.push({at:t,type:'egg'});t+=pause}sequence.push({at:t,type:'gift'},{at:t+1.5,type:'leave'},{at:t+3,type:'end'});return t+3}
