function buildParticles(){model.updateMatrixWorld(true);model.traverse(o=>{if(o.isSkinnedMesh)o.skeleton.update()});let positions=[],randoms=[];const v=new THREE.Vector3();model.traverse(o=>{if(!o.isMesh||!o.visible||!o.geometry.attributes.position||o.name.includes('eyelash')||o.name.includes('teeth'))return;const count=o.geometry.attributes.position.count;const stride=Math.max(1,Math.floor(count/2400));for(let i=0;i<count;i+=stride){o.getVertexPosition(i,v);o.localToWorld(v);if(v.y<1.1)continue;positions.push(v.x,v.y,v.z);randoms.push(Math.random(),Math.random(),Math.random())}});const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.setAttribute('aRandom',new THREE.Float32BufferAttribute(randoms,3));const m=new THREE.ShaderMaterial({transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,uniforms:{uReveal:{value:1},uTime:{value:0},uDpr:{value:Math.min(devicePixelRatio,1.5)}},vertexShader:`attribute vec3 aRandom;uniform float uReveal;uniform float uTime;uniform float uDpr;varying float vAlpha;void main(){float spread=1.0-uReveal;vec3 p=position; p+=(aRandom-.5)*spread*1.2; p.y+=sin(aRandom.x*20.0+uTime*.6)*spread*.18;vec4 mv=modelViewMatrix*vec4(p,1.0);gl_Position=projectionMatrix*mv;gl_PointSize=min(7.0,(1.4+aRandom.y*1.6)*uDpr/max(.4,-mv.z));vAlpha=sin(clamp(uReveal,0.0,1.0)*3.14159)*.85+spread*.15;}`,fragmentShader:`varying float vAlpha;void main(){float d=length(gl_PointCoord-.5);if(d>.5)discard;gl_FragColor=vec4(.72,1.0,.65,(1.0-smoothstep(.05,.5,d))*vAlpha);}`});particles=new THREE.Points(g,m);scene.add(particles)}
