if(mode==='speak'&&S.audio&&!S.audio.paused&&S.clip){const now=S.audio.currentTime;const chunks=S.clip.captionChunks;if(chunks?.length){const duration=S.audio.duration||S.clip.duration||1;caption(chunks[Math.min(chunks.length-1,Math.floor(now/duration*chunks.length))].trim())}let cue=S.clip.cues.find(c=>now>=c.start&&now<c.end);if(cue?.key){const duration=Math.max(.03,cue.end-cue.start),inout=Math.min(1,(now-cue.start)/.04,(cue.end-now)/.035);targets['viseme_'+cue.key]=Math.max(.15,inout)*.8;}set('browInnerUp',.08+.08*Math.sin(now*2));set('mouthSmileLeft',.06);set('mouthSmileRight',.06)}
