if(mode==='listen'){headY+=.07;headZ-=.035}if(mode==='doubt')headZ+=.075;if(mode==='think'){headX-=.04;headY+=.1}if(mode==='egg'&&age>.5){headX-=Math.exp(-(age-.5)*3)*.12;headZ+=Math.exp(-(age-.5)*3)*.1}if(mode==='speak'&&moving){headX+=Math.sin(t*2.3)*.025;headY+=Math.sin(t*.8)*.025}
