function spawnGift(){for(let i=0;i<18;i++){const m=new THREE.Mesh(new THREE.OctahedronGeometry(.008+Math.random()*.006),new THREE.MeshBasicMaterial({color:i%2?0xd6edb5:0xeec6ab,transparent:true}));m.position.set((Math.random()-.5)*.45,1.3+Math.random()*.2,.25);scene.add(m);effects.push({mesh:m,born:clock.elapsedTime,kind:'gift',speed:.05+Math.random()*.07})}}
